def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find positions of 2s and 3s
    twos = []
    threes = []
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 2:
                twos.append((r, c))
            elif val == 3:
                threes.append((r, c))

    result = [list(row) for row in grid]

    if not twos or not threes:
        return result

    # Get bounding boxes
    min_2_r = min(r for r, c in twos)
    max_2_r = max(r for r, c in twos)
    min_2_c = min(c for r, c in twos)
    max_2_c = max(c for r, c in twos)

    min_3_r = min(r for r, c in threes)
    max_3_r = max(r for r, c in threes)
    min_3_c = min(c for r, c in threes)
    max_3_c = max(c for r, c in threes)

    # Same starting row = U-shape, different = L-shape
    if min_2_r == min_3_r:
        # U-shape: verticals at 3-columns, then horizontal, then rectangle at bottom
        for c in [min_3_c, max_3_c]:
            for r in range(min_3_r, rows):
                if (r, c) not in twos:
                    result[r][c] = 3

        hr = max_3_r + 2
        for c in [min_3_c, max_3_c]:
            if 0 <= hr < rows:
                result[hr][c] = 3

        lb, rb = min_2_c + 1, max_2_c - 1
        bottom = min(hr + 1, rows)
        for r in range(hr, bottom):
            for c in range(lb, rb + 1):
                if 0 <= r < rows and 0 <= c < cols:
                    if result[r][c] not in [2, 3]:
                        result[r][c] = 3
    else:
        # L-shape: extra 3 from 3s to 2s
        corner_r, corner_c = max_3_r, min_2_c

        # Vertical from 3s region to corner
        for r in range(max_3_r, min_3_r - 1, -1):
            if result[r][corner_c] not in [2, 3]:
                result[r][corner_c] = 3

        # Horizontal from corner to 3s region
        for c in range(min_3_c, max_3_c + 1):
            if result[corner_r][c] not in [2, 3]:
                result[corner_r][c] = 3

        # Vertical at corner column through 2s region
        for r in range(corner_r, max_2_r + 1):
            if result[r][corner_c] not in [2, 3]:
                result[r][corner_c] = 3

    # Preserve original 2s and 3s
    for r, c in twos:
        result[r][c] = 2
    for r, c in threes:
        result[r][c] = 3

    return result
